CREATE SCHEMA c;
CREATE TABLE c.d_assignment(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_attachment(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_building(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_campaign(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_capture(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_client(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_commit(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_deal(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_decision(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_decision_event(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_defect(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_deployment(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_doctrine_document(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_doctrine_section(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_engagement(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_event(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_f01_corporate_artifact(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_f01_document(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_format(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_incident(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_job_receipt(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_lead(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_loop(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_next_action(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_party(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_pillar(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_platform(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_property_negotiation(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_record_flag(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_record_source(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_relationship(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_repo(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_rule(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_run(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_siep_package(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_vendor(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.d_work_request(id uuid PRIMARY KEY,payload text NOT NULL);
CREATE TABLE c.l_doctrine_link(id uuid PRIMARY KEY,src_id uuid NOT NULL REFERENCES c.d_doctrine_section(id),dst_kind text NOT NULL CHECK(dst_kind IN ('doctrine_document','doctrine_section','party','deal','decision','rule','loop','capture')),dst_id uuid NOT NULL,relation text NOT NULL CHECK(relation IN ('citation','related','example','source')));
CREATE INDEX ON c.l_doctrine_link(src_id);
CREATE INDEX ON c.l_doctrine_link(dst_kind,dst_id);
CREATE TABLE c.l_incident_link(id uuid PRIMARY KEY,src_id uuid NOT NULL REFERENCES c.d_incident(id),dst_kind text NOT NULL CHECK(dst_kind IN ('run','deployment','work_request','defect','decision')),dst_id uuid NOT NULL,relation text NOT NULL CHECK(relation IN ('reference')),UNIQUE(src_id,dst_kind,dst_id,relation));
CREATE INDEX ON c.l_incident_link(src_id);
CREATE INDEX ON c.l_incident_link(dst_kind,dst_id);
CREATE TABLE c.l_siep_evidence_link(id uuid PRIMARY KEY,src_id uuid NOT NULL REFERENCES c.d_siep_package(id),dst_kind text NOT NULL CHECK(dst_kind IN ('job_receipt','decision_event')),dst_id uuid NOT NULL,relation text NOT NULL CHECK(relation IN ('source','tests','migration','deploy','readback','live_readback','rollback','independent_review','joe_approval','joe_go_no_go','zero_unresolved_findings','zero_blockers','two_clean_audit_cycles','material_fix')),UNIQUE(src_id,dst_kind,dst_id));
CREATE INDEX ON c.l_siep_evidence_link(src_id);
CREATE INDEX ON c.l_siep_evidence_link(dst_kind,dst_id);
CREATE TABLE c.l_f01_derivative_link(id uuid PRIMARY KEY,src_id uuid NOT NULL REFERENCES c.d_f01_corporate_artifact(id),dst_kind text NOT NULL,dst_id uuid NOT NULL,relation text NOT NULL CHECK(relation IN ('reference')),UNIQUE(dst_kind,dst_id));
CREATE INDEX ON c.l_f01_derivative_link(src_id);
CREATE INDEX ON c.l_f01_derivative_link(dst_kind,dst_id);
CREATE TABLE c.l_j102_document_link(id uuid PRIMARY KEY,src_id uuid NOT NULL,dst_kind text NOT NULL CHECK(dst_kind IN ('relationship','engagement','assignment','property_negotiation','deal')),dst_id uuid NOT NULL,relation text NOT NULL CHECK(relation IN ('reference')),UNIQUE(src_id,dst_kind,dst_id,relation));
CREATE INDEX ON c.l_j102_document_link(src_id);
CREATE INDEX ON c.l_j102_document_link(dst_kind,dst_id);
CREATE TABLE c.l_j102_artifact_link(id uuid PRIMARY KEY,src_id uuid NOT NULL,dst_kind text NOT NULL CHECK(dst_kind IN ('relationship','engagement','assignment','property_negotiation','deal')),dst_id uuid NOT NULL,relation text NOT NULL CHECK(relation IN ('reference')),UNIQUE(src_id,dst_kind,dst_id,relation));
CREATE INDEX ON c.l_j102_artifact_link(src_id);
CREATE INDEX ON c.l_j102_artifact_link(dst_kind,dst_id);
CREATE TABLE c.l_event(id uuid PRIMARY KEY,src_id uuid NOT NULL,dst_kind text NOT NULL,dst_id uuid NOT NULL,relation text NOT NULL CHECK(relation IN ('reference')));
CREATE INDEX ON c.l_event(src_id);
CREATE INDEX ON c.l_event(dst_kind,dst_id);
CREATE TABLE c.l_record_source(id uuid PRIMARY KEY,src_id uuid NOT NULL,dst_kind text NOT NULL,dst_id uuid NOT NULL,relation text NOT NULL CHECK(relation IN ('reference')));
CREATE INDEX ON c.l_record_source(src_id);
CREATE INDEX ON c.l_record_source(dst_kind,dst_id);
CREATE TABLE c.l_next_action(id uuid PRIMARY KEY,src_id uuid NOT NULL,dst_kind text NOT NULL CHECK(dst_kind IN ('deal','client','lead','vendor')),dst_id uuid NOT NULL,relation text NOT NULL CHECK(relation IN ('reference')));
CREATE INDEX ON c.l_next_action(src_id);
CREATE INDEX ON c.l_next_action(dst_kind,dst_id);
CREATE TABLE c.l_record_flag(id uuid PRIMARY KEY,src_id uuid NOT NULL,dst_kind text NOT NULL CHECK(dst_kind IN ('lead','client','vendor','party','deal','campaign','platform','pillar','format','repo','commit')),dst_id uuid NOT NULL,relation text NOT NULL CHECK(relation IN ('reference')));
CREATE INDEX ON c.l_record_flag(src_id);
CREATE INDEX ON c.l_record_flag(dst_kind,dst_id);
CREATE TABLE c.l_attachment(id uuid PRIMARY KEY,src_id uuid NOT NULL,dst_kind text NOT NULL,dst_id uuid NOT NULL,relation text NOT NULL CHECK(relation IN ('reference')));
CREATE INDEX ON c.l_attachment(src_id);
CREATE INDEX ON c.l_attachment(dst_kind,dst_id);
CREATE VIEW c.relationships AS SELECT id,'doctrine_link'::text family,'doctrine_section'::text src_kind,src_id,dst_kind,dst_id,relation FROM c.l_doctrine_link UNION ALL SELECT id,'incident_link'::text family,'incident'::text src_kind,src_id,dst_kind,dst_id,relation FROM c.l_incident_link UNION ALL SELECT id,'siep_evidence_link'::text family,'siep_package'::text src_kind,src_id,dst_kind,dst_id,relation FROM c.l_siep_evidence_link UNION ALL SELECT id,'f01_derivative_link'::text family,'f01_corporate_artifact'::text src_kind,src_id,dst_kind,dst_id,relation FROM c.l_f01_derivative_link UNION ALL SELECT id,'j102_document_link'::text family,'f01_document'::text src_kind,src_id,dst_kind,dst_id,relation FROM c.l_j102_document_link UNION ALL SELECT id,'j102_artifact_link'::text family,'f01_corporate_artifact'::text src_kind,src_id,dst_kind,dst_id,relation FROM c.l_j102_artifact_link UNION ALL SELECT id,'event'::text family,'event'::text src_kind,src_id,dst_kind,dst_id,relation FROM c.l_event UNION ALL SELECT id,'record_source'::text family,'record_source'::text src_kind,src_id,dst_kind,dst_id,relation FROM c.l_record_source UNION ALL SELECT id,'next_action'::text family,'next_action'::text src_kind,src_id,dst_kind,dst_id,relation FROM c.l_next_action UNION ALL SELECT id,'record_flag'::text family,'record_flag'::text src_kind,src_id,dst_kind,dst_id,relation FROM c.l_record_flag UNION ALL SELECT id,'attachment'::text family,'attachment'::text src_kind,src_id,dst_kind,dst_id,relation FROM c.l_attachment;
